const mkId=()=>globalThis.crypto?.randomUUID?.()||'id'+Math.random().toString(36).slice(2);
let state={user:null,page:'dashboard',surveys:[],contacts:[],assignments:[],users:[],dashboard:null,filter:'',statusFilter:'all',selectedContacts:new Set(),builder:null,builderQ:null,builderSection:null,propOpen:false,preview:false,interview:null,interviewIndex:0,interviewDone:false,report:null,reportSurveyId:null,reportTab:'summary',mobile:false,dirty:false};
async function request(url,opts={}){const res=await fetch(url,{credentials:'same-origin',...opts,headers:{...(opts.body?{'Content-Type':'application/json'}:{}),...(opts.headers||{})}});let data;const ct=res.headers.get('content-type')||'';if(ct.includes('application/json'))data=await res.json();else data=await res.text();if(!res.ok){if(res.status===401&&state.user){state.user=null;renderLogin();}throw new Error(data?.error||`HTTP ${res.status}`);}return data;}
const api=(url,data,method='POST')=>request(url,{method,body:JSON.stringify(data)});
function notify(text,bad=false){const div=document.createElement('div');div.className='toast'+(bad?' error':'');div.innerHTML=ico(bad?'info':'check',17)+'<span>'+esc(text)+'</span>';$('#toast-root').appendChild(div);setTimeout(()=>div.remove(),4200);}
async function init(){try{const {user}=await request('/api/me');state.user=user;await refresh();route();}catch{renderLogin();}}
async function refresh(){const load=[request('/api/surveys'),request('/api/contacts'),request('/api/assignments'),request('/api/dashboard')];if(state.user?.role==='admin')load.push(request('/api/users'));const results=await Promise.all(load);state.surveys=results[0].surveys;state.contacts=results[1].contacts;state.assignments=results[2].assignments;state.dashboard=results[3];state.users=results[4]?.users||[];}
function renderLogin(){state.page='login';$('#app').innerHTML=`<div class="login-page"><div class="login-visual"><div class="brand"><span class="brand-icon">${ico('spark',23)}</span><span><span class="brand-name">SorğuPro</span><span class="brand-desc">SURVEY INTELLIGENCE PLATFORM</span></span></div><div class="login-promo"><div class="login-kicker">Yeni nəsil sorğu idarəetməsi</div><h1>Hər cavab<br><em>dəyərli məlumatdır.</em></h1><p>Telefon sorğuları, operator işi, ağıllı sual formaları və real vaxt analitikası — hamısı vahid platformada.</p><div class="login-graphic"><div class="mini-bars">${[32,49,41,65,54,76,68,92].map(x=>`<i style="height:${x}%"></i>`).join('')}</div><div class="login-metric"><strong>360°</strong><small>Kompleks analiz<br>Bir platforma</small></div></div></div><div class="login-visual-foot"><span><i class="dot-live"></i>İnteqrə sorğu mühiti</span><span>© 2026 SorğuPro</span></div></div><div class="login-form-side"><form class="login-form" id="login-form"><div class="login-splash">${ico('lock',27)}</div><h2>Xoş gəlmisiniz!</h2><p>İş mühitinizə keçmək üçün hesab məlumatlarınızla daxil olun.</p><div class="field"><label>İstifadəçi adı</label><div class="input-icon">${ico('users',17)}<input name="username" autocomplete="username" placeholder="İstifadəçi adınızı daxil edin" required autofocus></div></div><div class="field"><label>Şifrə</label><div class="input-icon">${ico('lock',17)}<input type="password" name="password" autocomplete="current-password" placeholder="Şifrənizi daxil edin" required></div></div><div id="login-error"></div><button class="btn btn-primary btn-lg w100" style="margin-top:12px" type="submit">Sistemə daxil ol ${ico('arrow',17)}</button><div class="login-demo"><b>Demo giriş:</b> Administrator: <b>admin</b> / <b>Admin@2026!</b><br>Operator: <b>operator1</b> / <b>Agent@2026!</b><br><span style="font-size:10px">Həqiqi istifadədən əvvəl bu şifrələri dəyişin.</span></div><div class="login-copy">Qorunan giriş · Rol əsaslı icazələr · Təhlükəsiz sessiya</div></form></div></div>`;}
const NAV=[['dashboard','İdarə paneli','dashboard'],['surveys','Sorğular','surveys'],['tasks','Zəng tapşırıqları','tasks'],['contacts','Respondentlər','contacts'],['reports','Hesabatlar','reports'],['team','Operatorlar','team'],['settings','Parametrlər','settings']];
function navigate(page){if(state.dirty&&['builder','interview'].includes(state.page)&&page!==state.page&&!confirm('Yadda saxlanmamış dəyişikliklər var. Səhifəni tərk etmək istəyirsiniz?'))return;state.page=page;state.filter='';state.statusFilter='all';state.dirty=false;state.preview=false;location.hash='#/'+page;render();window.scrollTo(0,0);}
function route(){const p=location.hash.match(/^#\/([\w-]+)/)?.[1]||'dashboard';if(state.user) {state.page=['dashboard','surveys','tasks','contacts','reports','team','settings','builder','interview'].includes(p)?p:'dashboard';if(state.page==='builder'||state.page==='interview')state.page='dashboard';render();}}
function shell(){const admin=state.user.role==='admin';const p=state.page;const nav=NAV.filter(([id])=>admin||!['reports','team'].includes(id));const label=NAV.find(([id])=>id===p)?.[1]|| (p==='builder'?'Sorğu konstruktoru':p==='interview'?'Müsahibə forması':'');return `<div class="shell"><div class="mobile-scrim ${state.mobile?'show':''}" data-action="close-mobile"></div><aside class="sidebar ${state.mobile?'open':''}"><div class="side-brand"><div class="brand"><span class="brand-icon">${ico('spark',22)}</span><span><span class="brand-name">SorğuPro</span><span class="brand-desc">INTELLIGENCE STUDIO</span></span></div></div><nav class="nav-box"><div class="nav-label">İŞ MÜHİTİ</div>${nav.map(([id,text,icon])=>`<button class="nav-link ${p===id?'active':''}" data-action="nav" data-page="${id}" style="width:100%;border:0;text-align:left">${ico(icon,18)}<span>${text}</span>${id==='tasks'&&state.dashboard?.stats?.pending?`<span class="nav-count">${state.dashboard.stats.pending}</span>`:''}</button>`).join('')}<div class="nav-label">SİSTEM</div><div class="nav-link" style="cursor:default">${ico('shield',18)}<span>Təhlükəsiz giriş</span><span class="nav-count">●</span></div></nav><div class="side-bottom"><div class="side-assist"><b>${ico('spark',14)} &nbsp; SorğuPro Studio</b><p>Kompleks sorğuları qurun, zəngləri idarə edin və nəticələri analiz edin.</p></div><div class="side-user"><div class="avatar">${esc(initials(state.user.name))}</div><div class="side-user-text"><strong>${esc(state.user.name)}</strong><small>${admin?'Sistem administratoru':'Sorğu operatoru'}</small></div><button class="signout" data-action="logout" title="Çıxış">${ico('logout',17)}</button></div></div></aside><div class="main"><header class="topbar"><div class="gap10"><button class="mobile-toggle" data-action="toggle-mobile">${ico('menu',20)}</button><div class="crumb">İş mühiti ${ico('chevron',14)} <strong>${esc(label)}</strong></div></div><div class="top-actions"><div class="search-box">${ico('search',15)}<input id="global-search" placeholder="Sürətli axtarış..." aria-label="Sürətli axtarış" value="${esc(state.filter)}"></div><span class="top-time">${new Date().toLocaleDateString('az-AZ',{day:'numeric',month:'long',year:'numeric'})}</span><div class="top-avatar">${esc(initials(state.user.name))}</div></div></header><main class="content ${p==='builder'?'builder-content':''}" id="page-content">${page()}</main></div></div>`;}
function page(){switch(state.page){case'dashboard':return dashboardPage();case'surveys':return surveysPage();case'contacts':return contactsPage();case'tasks':return tasksPage();case'reports':return reportsPage();case'team':return teamPage();case'settings':return settingsPage();case'builder':return builderPage();case'interview':return interviewPage();default:return dashboardPage();}}
function render(){if(!state.user)return renderLogin();$('#app').innerHTML=shell();}
const heading=(k,title,sub,buttons='')=>`<div class="page-heading"><div><div class="eyebrow">${k}</div><h1>${title}</h1><p>${sub}</p></div><div class="heading-actions">${buttons}</div></div>`;
function empty(icon,title,text,button=''){return `<div class="empty">${ico(icon,39)}<h3>${esc(title)}</h3><p>${esc(text)}</p>${button}</div>`;}
function dashboardPage(){const x=state.dashboard||{stats:{},days:[],recent:[],byStatus:{}};const z=x.stats,admin=state.user.role==='admin';const cards=[['Aktiv sorğular',z.activeSurveys,'Hazırda yayımlanan sorğular','surveys',''],['Tapşırıqlar',z.totalAssignments,'Respondent zəng siyahısı','phone','mint'],['Tamamlanan',z.completed,'Yekunlaşdırılmış müsahibələr','check','blue'],['İcra göstəricisi',(z.completionRate||0)+'%','Bütün tapşırıqlar üzrə','chart','orange']];const max=Math.max(1,...x.days.map(d=>Math.max(d.calls,d.completed)));return `${heading('İDARƏ PANELİ','Salam, '+esc(state.user.name.split(' ')[0])+'!','İş axınına nəzarət edin, zəngləri və sorğu göstəricilərini izləyin.',`<button class="btn" data-action="refresh">${ico('refresh',16)} Yenilə</button>${admin?`<button class="btn btn-primary" data-action="new-survey">${ico('plus',16)} Yeni sorğu</button>`:''}`)}<div class="welcome-banner"><div><h2>Məlumatı topla. Dəqiq qərar ver.</h2><p>${admin?'Sorğuların hazırlanması, operatorların idarə edilməsi və analitika bir mərkəzdə.':'Bu gün üçün tapşırıqlarınızı izləyin, respondentlərlə əlaqə saxlayın və cavabları sistemə daxil edin.'}</p></div><button class="btn" data-action="nav" data-page="${admin?'surveys':'tasks'}">${admin?'Sorğuları idarə et':'Zənglərə başla'} ${ico('arrow',15)}</button></div><div class="grid cols-4">${cards.map(([title,val,desc,icon,color])=>`<div class="card stat-card"><div class="stat-head"><span class="stat-label">${title}</span><span class="stat-icon ${color}">${ico(icon,20)}</span></div><div class="stat-value">${pl(String(val).replace('%',''))}${String(val).endsWith('%')?'%':''}</div><div class="stat-foot">${desc}</div></div>`).join('')}</div><div class="grid cols-3 mt20"><div class="card span-2"><div class="card-head"><div><h3>Fəaliyyət dinamikası</h3><p>Son 7 günün tamamlanan sorğuları və zəngləri</p></div><div class="legend"><span>Zənglər</span><span class="mint">Sorğular</span></div></div><div class="dashboard-chart"><div class="chart-area">${x.days.map(d=>`<div class="chart-group"><div class="bar" title="Zənglər: ${d.calls}" style="height:${Math.max(2,d.calls/max*92)}%"></div><div class="bar second" title="Tamamlanan: ${d.completed}" style="height:${Math.max(2,d.completed/max*92)}%"></div></div>`).join('')}</div><div class="chart-x">${x.days.map(d=>`<span>${fmtDate(d.date,true)}</span>`).join('')}</div></div></div><div class="card"><div class="card-head"><div><h3>Zəng statusları</h3><p>Tapşırıqlar üzrə bölgü</p></div>${ico('chart',18)}</div><div class="card-body">${Object.entries(x.byStatus).filter(([k])=>['completed','pending','callback','refused','no_answer','busy'].includes(k)).map(([k,val])=>`<div class="status-row"><label>${OUTCOME[k]}</label><div class="progress-line"><span style="width:${z.totalAssignments?val/z.totalAssignments*100:0}%;background:${({completed:'#25b999',pending:'#a5a8bb',callback:'#efb158',refused:'#ef7385',no_answer:'#8b81eb',busy:'#9ec6e9'})[k]}"></span></div><b>${val}</b></div>`).join('')}<div class="highlight-box">${ico('info',14)} &nbsp; Tamamlanma faizi: <b>${z.completionRate||0}%</b></div></div></div></div><div class="card mt20"><div class="card-head"><div><h3>Son fəaliyyətlər</h3><p>Ən son yenilənən zəng tapşırıqları</p></div><button class="section-link" data-action="nav" data-page="tasks">Hamısına bax ${ico('arrow',14)}</button></div><div class="table-wrap"><table class="table"><thead><tr><th>Respondent</th><th>Sorğu</th>${admin?'<th>Operator</th>':''}<th>Status</th><th>Son yenilənmə</th><th></th></tr></thead><tbody>${x.recent.map(a=>`<tr><td><b>${esc(a.contact?.fullName||'—')}</b><div class="table-desc">${esc(a.contact?.phone)}</div></td><td>${esc(a.survey||'—')}</td>${admin?`<td>${esc(a.agent||'—')}</td>`:''}<td>${outcomeBadge(a.status)}</td><td>${fmtTime(a.updatedAt)}</td><td><button class="btn btn-sm" data-action="start-interview" data-id="${a.id}">${ico('chevron',14)} Aç</button></td></tr>`).join('')||`<tr><td colspan="6">${empty('phone','Tapşırıq tapılmadı','Yeni tapşırıqlar əlavə etdikdən sonra burada görünəcək.')}</td></tr>`}</tbody></table></div></div>`;}
function filtered(list,terms){const needle=state.filter.toLowerCase().trim();return needle?list.filter(x=>terms(x).toLowerCase().includes(needle)):list;}
function surveysPage(){const admin=state.user.role==='admin';let list=filtered(state.surveys,s=>s.title+' '+s.description+' '+s.category);if(state.statusFilter!=='all')list=list.filter(s=>s.status===state.statusFilter);return `${heading('SORĞU STUDİYASI','Sorğu kitabxanası','Dinamik sual modulları, şaxələnmə məntiqi və çoxbölməli sorğular.',admin?`<button class="btn btn-primary" data-action="new-survey">${ico('plus',16)} Yeni sorğu yarat</button>`:'')}<div class="filter-strip"><input class="filter-input" data-local-search placeholder="Sorğu adı və kateqoriya üzrə axtar..." value="${esc(state.filter)}"><select class="filter-select" data-status-filter><option value="all">Bütün statuslar</option>${['active','draft','paused','archived'].map(v=>`<option value="${v}" ${state.statusFilter===v?'selected':''}>${OUTCOME[v]}</option>`).join('')}</select><span class="pill">${list.length} sorğu</span></div><div class="grid cols-3">${list.map(s=>`<article class="card survey-card"><div class="survey-top"><div class="survey-icon">${ico('surveys',23)}</div>${outcomeBadge(s.status)}</div><h3>${esc(s.title)}</h3><p>${esc(s.description||'Sorğu haqqında təsvir əlavə edilməyib.')}</p><div class="survey-metrics"><span><b>${s.questionsCount}</b>Sual</span><span><b>${s.assignmentsCount}</b>Təyinat</span><span><b>${s.responsesCount}</b>Cavab</span><span><b>${s.estimatedMinutes} dəq.</b>Müddət</span></div><div class="survey-actions">${admin?`<button class="btn btn-primary" data-action="edit-survey" data-id="${s.id}">${ico('edit',14)} Redaktə</button><button class="btn btn-icon" title="Surətini yarat" data-action="duplicate-survey" data-id="${s.id}">${ico('copy',15)}</button><button class="btn btn-icon" title="Statusu dəyiş" data-action="survey-status" data-id="${s.id}">${ico('more',16)}</button>`:`<button class="btn btn-primary w100" data-action="nav" data-page="tasks">${ico('phone',14)} Tapşırıqlara bax</button>`}</div></article>`).join('')}</div>${list.length?'':empty('surveys','Sorğu tapılmadı','Axtarışı dəyişin və ya ilk sorğunuzu yaradın.',admin?`<button class="btn btn-primary" data-action="new-survey">Yeni sorğu</button>`:'')}`;}
function contactsPage(){let list=filtered(state.contacts,c=>c.fullName+' '+c.phone+' '+c.email+' '+c.region);const admin=state.user.role==='admin';return `${heading('RESPONDENT BAZASI','Respondentlər','Əlaqə məlumatlarını idarə edin və sorğulara təyin edin.',`<button class="btn" data-action="import-contacts">${ico('upload',16)} CSV idxalı</button><button class="btn btn-primary" data-action="new-contact">${ico('plus',16)} Respondent əlavə et</button>`)}<div class="filter-strip"><input class="filter-input" data-local-search placeholder="Ad, telefon və ya region üzrə axtar..." value="${esc(state.filter)}"><span class="pill">${pl(list.length)} respondent</span>${state.selectedContacts.size?`<span class="select-count">${state.selectedContacts.size} seçilib</span><button class="btn btn-primary" data-action="assign-selected">${ico('plus',14)} Sorğuya təyin et</button>`:''}</div><div class="card"><div class="table-wrap"><table class="table"><thead><tr><th><input class="check" type="checkbox" data-action="select-all-contacts" ${list.length&&list.every(c=>state.selectedContacts.has(c.id))?'checked':''}></th><th>Ad və soyad</th><th>Telefon</th><th>Region</th><th>E-poçt</th><th>Əlavə edilmə</th><th></th></tr></thead><tbody>${list.map(c=>`<tr><td><input class="check contact-check" type="checkbox" data-id="${c.id}" ${state.selectedContacts.has(c.id)?'checked':''}></td><td><div class="gap10"><span class="person-avatar" style="height:33px;width:33px;border-radius:9px;font-size:11px">${esc(initials(c.fullName))}</span><b>${esc(c.fullName)}</b></div></td><td>${esc(c.phone)}</td><td>${esc(c.region||'—')}</td><td>${esc(c.email||'—')}</td><td>${fmtDate(c.createdAt)}</td><td><button class="btn btn-icon btn-sm" data-action="edit-contact" data-id="${c.id}" title="Dəyişdir">${ico('edit',15)}</button></td></tr>`).join('')||`<tr><td colspan="7">${empty('contacts','Respondent tapılmadı','Yeni respondent əlavə edin və ya CSV faylı idxal edin.')}</td></tr>`}</tbody></table></div></div>`;}
function tasksPage(){let list=filtered(state.assignments,a=>(a.contact?.fullName||'')+' '+(a.contact?.phone||'')+' '+a.survey+' '+a.agent);if(state.statusFilter!=='all')list=list.filter(a=>a.status===state.statusFilter);const admin=state.user.role==='admin';return `${heading('ZƏNG MƏRKƏZİ','Zəng tapşırıqları','Respondentlərlə əlaqəni və müsahibə statuslarını bir yerdə idarə edin.',`<button class="btn btn-primary" data-action="assign-selected">${ico('plus',16)} Yeni təyinat</button>`)}<div class="filter-strip"><input class="filter-input" data-local-search placeholder="Respondent, telefon və ya sorğu üzrə axtar..." value="${esc(state.filter)}"><select class="filter-select" data-status-filter><option value="all">Bütün statuslar</option>${['pending','in_progress','callback','no_answer','busy','refused','completed'].map(v=>`<option value="${v}" ${state.statusFilter===v?'selected':''}>${OUTCOME[v]}</option>`).join('')}</select><span class="pill">${list.length} tapşırıq</span></div><div class="card"><div class="table-wrap"><table class="table"><thead><tr><th>Respondent</th><th>Sorğu</th>${admin?'<th>Operator</th>':''}<th>Cəhd</th><th>Prioritet</th><th>Status</th><th></th></tr></thead><tbody>${list.map(a=>`<tr><td><b>${esc(a.contact?.fullName||'—')}</b><div class="table-desc">${ico('phone',11)} ${esc(a.contact?.phone||'—')}</div></td><td><span style="display:block;max-width:225px;line-height:1.55">${esc(a.survey||'—')}</span>${a.callbackAt?`<div class="table-desc">${ico('clock',11)} ${fmtTime(a.callbackAt)}</div>`:''}</td>${admin?`<td>${esc(a.agent)}</td>`:''}<td>${a.attempts||0}</td><td><span class="pill" style="${a.priority==='high'?'color:#d68a39;background:#fff5e7':''}">${a.priority==='high'?'Yüksək':a.priority==='low'?'Aşağı':'Normal'}</span></td><td>${outcomeBadge(a.status)}</td><td><div class="inline-actions"><button class="btn btn-sm ${a.status==='completed'?'':'btn-primary'}" data-action="start-interview" data-id="${a.id}">${ico(a.status==='completed'?'eye':'phone',14)} ${a.status==='completed'?'Bax':'Başla'}</button><button class="btn btn-icon btn-sm" title="Zəng nəticəsi" data-action="call-result" data-id="${a.id}">${ico('more',16)}</button></div></td></tr>`).join('')||`<tr><td colspan="8">${empty('phone','Zəng tapşırığı tapılmadı','Yeni təyinat yaradın və ya axtarış filtrini dəyişin.')}</td></tr>`}</tbody></table></div></div>`;}
function reportsPage(){const list=state.surveys;return `${heading('ANALİTİKA','Hesabatlar','Sorğu nəticələrini analiz edin, cavab bölgüsünə baxın və CSV ixrac edin.')}${!state.report?`<div class="grid cols-3">${list.map(s=>`<div class="card survey-card"><div class="survey-top"><div class="survey-icon">${ico('chart',23)}</div>${outcomeBadge(s.status)}</div><h3>${esc(s.title)}</h3><p>${esc(s.description)}</p><div class="survey-metrics"><span><b>${s.responsesCount}</b>Cavab</span><span><b>${s.assignmentsCount}</b>Təyinat</span></div><div class="survey-actions"><button class="btn btn-primary" data-action="open-report" data-id="${s.id}">${ico('chart',15)} Hesabatı aç</button><button class="btn btn-icon" data-action="export-report" data-id="${s.id}" title="CSV ixrac">${ico('download',15)}</button></div></div>`).join('')}</div>`:reportDetail()}`;}
function reportDetail(){const r=state.report;return `<button class="btn" style="margin-bottom:19px" data-action="close-report">${ico('back',14)} Bütün hesabatlar</button><div class="card" style="padding:24px 26px;margin-bottom:19px"><div style="display:flex;justify-content:space-between;gap:15px;flex-wrap:wrap"><div><div class="eyebrow">SORĞU HESABATI</div><h2 style="font-size:21px;margin:0 0 10px">${esc(r.survey.title)}</h2>${outcomeBadge(r.survey.status)}</div><button class="btn btn-primary" data-action="export-report" data-id="${r.survey.id}">${ico('download',16)} Excel üçün CSV</button></div><div class="grid cols-4 mt20"><div class="report-metric"><span>Cəmi təyinat</span><b>${r.totalAssigned}</b></div><div class="report-metric"><span>Tamamlanan cavab</span><b>${r.completed}</b></div><div class="report-metric"><span>İcra faizi</span><b>${r.totalAssigned?Math.round(r.completed/r.totalAssigned*100):0}%</b></div><div class="report-metric"><span>Ort. müsahibə müddəti</span><b>${Math.round(r.averageDuration/60)} dəq.</b></div></div></div><div class="card"><div class="tabs"><button class="tab ${state.reportTab==='summary'?'active':''}" data-action="report-tab" data-tab="summary">${ico('chart',15)} &nbsp; Sual analitikası</button><button class="tab ${state.reportTab==='responses'?'active':''}" data-action="report-tab" data-tab="responses">${ico('list',15)} &nbsp; Cavab reyestri</button></div>${state.reportTab==='summary'?r.questions.map((q,i)=>`<div class="report-q"><div class="gap10"><span class="pill">${i+1}</span><h4 style="margin:0">${esc(q.title)}</h4></div><small>${typeLabel(q.type)} · ${q.answered} cavab</small>${q.average!==null?`<div class="highlight-box">Orta göstərici: <b>${q.average}</b></div>`:''}${q.counts.length?q.counts.slice(0,9).map(([label,count])=>`<div class="report-entry"><span>${esc(label)}</span><div class="progress-line"><span style="width:${q.answered?Math.min(100,count/q.answered*100):0}%;background:#7969ea"></span></div><b>${count}</b></div>`).join(''):q.samples.length?q.samples.map(v=>`<p class="note" style="margin:13px 0">“${esc(v)}”</p>`).join(''):'<div class="note mt12">Məlumat yoxdur və ya cavablar sərbəst formatdadır.</div>'}</div>`).join(''): `<div class="table-wrap"><table class="table"><thead><tr><th>Respondent</th><th>Operator</th><th>Tarix</th><th>Müddət</th><th></th></tr></thead><tbody>${r.responses.map(x=>`<tr><td><b>${esc(x.contact||'—')}</b></td><td>${esc(x.agent||'—')}</td><td>${fmtTime(x.submittedAt)}</td><td>${Math.ceil(x.durationSec/60)} dəq.</td><td><button class="btn btn-sm" data-action="response-details" data-id="${x.id}">${ico('eye',14)} Bax</button></td></tr>`).join('')||'<tr><td colspan="5">Cavab yoxdur.</td></tr>'}</tbody></table></div>`}</div>`;}
function teamPage(){const u=state.users;return `${heading('İSTİFADƏÇİ İDARƏETMƏSİ','Operator heyəti','İcazələri, hesabları və operatorların fəaliyyətini idarə edin.',`<button class="btn btn-primary" data-action="new-user">${ico('plus',16)} Yeni əməkdaş</button>`)}<div class="grid cols-3">${u.map(person=>{const assigned=state.assignments.filter(a=>a.assignedTo===person.id),done=assigned.filter(a=>a.status==='completed').length;return `<div class="card" style="padding:24px"><div class="gap10"><div class="person-avatar">${esc(initials(person.name))}</div><div style="flex:1"><b>${esc(person.name)}</b><div class="table-desc">@${esc(person.username)}</div></div><span class="badge ${person.active?'active':'refused'}">${person.active?'Aktiv':'Deaktiv'}</span></div><div class="separator"></div><div class="gap10" style="justify-content:space-between;font-size:11px;color:#8491a5"><span>${person.role==='admin'?'Administrator':'Operator'}</span><span>Tapşırıq: <b style="color:var(--ink)">${assigned.length}</b></span><span>Cavab: <b style="color:var(--ink)">${done}</b></span></div><div class="metric-bar"><span style="width:${assigned.length?done/assigned.length*100:0}%"></span></div><div class="gap10" style="justify-content:space-between;margin-top:14px"><span class="note">İcra: ${assigned.length?Math.round(done/assigned.length*100):0}%</span><button class="btn btn-sm" data-action="edit-user" data-id="${person.id}">${ico('edit',13)} İdarə et</button></div></div>`}).join('')}</div>`;}
function settingsPage(){return `${heading('HESAB VƏ TƏHLÜKƏSİZLİK','Parametrlər','Şəxsi profil, şifrə və platforma haqqında məlumatlar.') }<div class="grid cols-2"><div class="card list-card"><h3>Şəxsi profil</h3><p class="muted" style="font-size:12px">Cari istifadəçi məlumatları</p><div class="separator"></div>${[['Ad və soyad',state.user.name],['İstifadəçi adı',state.user.username],['Rol',state.user.role==='admin'?'Administrator':'Operator'],['Qeydiyyat tarixi',fmtDate(state.user.createdAt)]].map(([label,value])=>`<div class="info-pair"><span>${label}</span><span>${esc(value)}</span></div>`).join('')}<button class="btn mt20" data-action="change-password">${ico('lock',15)} Şifrəni dəyiş</button></div><div class="card list-card"><h3>Platforma haqqında</h3><p class="muted" style="font-size:12px">SorğuPro v1.0 · Professional Edition</p><div class="separator"></div><div class="gap10">${ico('shield',34)}<div><b>Qorunan sessiya və icazələr</b><p class="note mt12">Admin/operator rolları, şifrələrin kriptoqrafik heşlənməsi və şəxsi məlumatlara nəzarət.</p></div></div><div class="separator"></div><div class="gap10">${ico('layers',34)}<div><b>${TYPES.length} dinamik sual modulu</b><p class="note mt12">Şərtli göstərilmə, çoxbölməli müsahibə, qaralama və analitika.</p></div></div><div class="hint mt20">Məlumatlar bu serverdə saxlanılır. Serverin <b>data/</b> qovluğunu mütəmadi yedəkləyin.</div></div></div>`;}
// ——— FORM DESIGNER ———
function newQuestion(type,sectionId){const question={id:mkId(),sectionId,type,title:'Yeni sual',description:'',required:!['paragraph','file','consent'].includes(type),options:[],rows:[],columns:[],settings:{min:0,max:10},condition:null};if(['single','multiple','dropdown','image_choice','ranking','bestworst','text_ab','image_ab'].includes(type))question.options=['Variant 1','Variant 2','Variant 3'].map(label=>({id:mkId(),label,image:''}));if(type.startsWith('matrix')){question.rows=['Meyar 1','Meyar 2','Meyar 3'];question.columns=['Pis','Orta','Yaxşı','Əla'];}if(type==='multitext')question.rows=['Sahə 1','Sahə 2'];if(['rating','stars','likert'].includes(type)){question.settings={min:1,max:5};}if(type==='nps')question.settings={min:0,max:10};if(type==='percentage')question.settings={min:0,max:100};if(type==='slider')question.settings={min:0,max:10,step:1};if(type==='consent')question.title='Məlumatların emalına razılıq verirsinizmi?';return question;}
function makeBuilder(survey){state.builder=JSON.parse(JSON.stringify(survey));state.builderQ=survey.questions[0]?.id||null;state.builderSection=survey.sections[0]?.id||null;state.dirty=false;state.preview=false;state.propOpen=false;state.page='builder';location.hash='#/builder';render();window.scrollTo(0,0);}
function builderPage(){const s=state.builder;if(!s)return `<div class="empty">Sorğu seçilməyib.</div>`;const sel=s.questions.find(q=>q.id===state.builderQ);const qBySection=id=>s.questions.filter(q=>q.sectionId===id);return `<div class="builder-top"><div><div class="eyebrow">SORĞU KONSTRUKTORU ${state.dirty?'· YADDA SAXLANMAYIB':''}</div><h1>${esc(s.title)}</h1></div><div class="heading-actions"><button class="btn" data-action="open-properties">${ico('edit',15)} Sual parametrləri</button><button class="btn" data-action="survey-settings">${ico('settings',15)} Məlumatlar</button><button class="btn" data-action="builder-preview">${ico(state.preview?'edit':'eye',16)} ${state.preview?'Redaktor':'Önizləmə'}</button><button class="btn btn-primary" data-action="save-builder">${ico('save',16)} Yadda saxla</button><button class="btn btn-icon" data-action="nav" data-page="surveys" title="Çıxış">${ico('close',16)}</button></div></div><div class="builder-shell"><aside class="builder-panel"><div class="builder-panel-title">SUАL KİTABXANASI · ${TYPES.length}</div>${groups.map(group=>`<div class="palette-group"><div class="palette-label">${group}</div>${TYPES.filter(t=>t[0]===group).map(([g,type,label,icon])=>`<button class="palette-item" data-action="add-question" data-type="${type}">${ico(icon,15)} ${label}</button>`).join('')}</div>`).join('')}</aside><div class="builder-stage">${state.preview?builderPreview():`<div class="builder-intro"><small>${esc(s.category||'Ümumi')} / ${s.questions.length} sual / ${s.sections.length} bölmə</small><h2>${esc(s.title)}</h2><p>${esc(s.description||'Sorğunu konfiqurasiya etmək üçün sualları seçin.')}</p></div>${s.sections.map((sec,i)=>`<div class="section-band"><h3>${i+1 < 10?'0'+(i+1):i+1} — ${esc(sec.title)}</h3><div class="inline-actions"><button class="btn btn-sm" data-action="edit-section" data-id="${sec.id}">${ico('edit',13)}</button>${s.sections.length>1?`<button class="btn btn-sm" data-action="delete-section" data-id="${sec.id}">${ico('trash',13)}</button>`:''}</div></div>${qBySection(sec.id).map((q,i)=>`<div class="q-card ${state.builderQ===q.id?'selected':''}" data-action="select-question" data-id="${q.id}"><div class="qcard-top"><span class="q-number">${i+1}</span><div class="q-title">${esc(q.title)} ${q.required?'<span class="required">*</span>':''}<div class="q-mini-type">${typeLabel(q.type)}${q.condition?' · Şərt tətbiq edilib':''}</div></div><div class="q-actions"><button data-action="move-question" data-id="${q.id}" data-direction="-1" title="Yuxarı">↑</button><button data-action="move-question" data-id="${q.id}" data-direction="1" title="Aşağı">↓</button><button data-action="clone-question" data-id="${q.id}" title="Kopyala">${ico('copy',13)}</button><button data-action="delete-question" data-id="${q.id}" title="Sil">${ico('trash',13)}</button></div></div><div class="q-preview">${questionMini(q)}</div></div>`).join('')}<button class="builder-add" data-action="add-question" data-section="${sec.id}" data-type="single">${ico('plus',15)} Bu bölməyə sual əlavə et</button>`).join('')}<button class="builder-add" data-action="add-section">${ico('plus',15)} Yeni bölmə əlavə et</button>`}</div><aside class="builder-panel right ${sel&&state.propOpen?'show':''}" id="property-panel">${state.preview?`<div class="builder-panel-title">ÖNİZLƏMƏ</div><div class="prop-desc">Bu görüntü respondentə təqdim olunacaq interfeysə yaxındır.</div>`:sel?properties(sel):`<div class="builder-panel-title">SUАL PARAMETRLƏRİ</div>${empty('edit','Sual seçin','Soldakı kitabxanadan sual əlavə edin və ya ortadakı sualı seçin.')}`}</aside></div>`;}
function questionMini(q){const opt=q.options||[];if(['single','multiple','dropdown','yesno','image_choice','text_ab','image_ab'].includes(q.type))return `<div class="fake-options">${(q.type==='yesno'?['Bəli','Xeyr']:opt.map(x=>x.label)).slice(0,4).map(t=>`<span class="fake-option">◯ ${esc(t)}</span>`).join('')||'Variant əlavə edin'}</div>`;if(['rating','stars','slider','nps','likert'].includes(q.type))return `<div class="fake-options">${Array.from({length:5},(_,i)=>`<span class="fake-option">${q.type==='stars'?'☆':i+1}</span>`).join('')}</div>`;if(q.type.startsWith('matrix'))return `${q.rows.length} meyar × ${q.columns.length} cavab variantı`;return '<div class="fake-line">Cavab üçün sahə...</div>';}
function properties(q){const s=state.builder;const withOpts=['single','multiple','dropdown','image_choice','ranking','bestworst','text_ab','image_ab'].includes(q.type);const withRows=['matrix','matrix_multi','matrix_dropdown','multitext'].includes(q.type);const numeric=['slider','rating','stars','nps','likert','number','currency','percentage'].includes(q.type);return `<button class="btn btn-sm property-close" data-action="close-properties">${ico('close',14)} Paneli bağla</button><div class="builder-panel-title">SUАL PARAMETRLƏRİ</div><h3 class="prop-title">${esc(typeLabel(q.type))}</h3><p class="prop-desc">Sualın məzmununu, cavab variantlarını və məntiqini tənzimləyin.</p><div class="prop-fields"><div class="field"><label>Sual mətni</label><textarea data-builder-field="title" data-qid="${q.id}">${esc(q.title)}</textarea></div><div class="field"><label>İzah / köməkçi mətn</label><textarea data-builder-field="description" data-qid="${q.id}" style="min-height:60px">${esc(q.description)}</textarea></div><label class="toggle-wrap"><input class="toggle" type="checkbox" data-builder-field="required" data-qid="${q.id}" ${q.required?'checked':''}> Məcburi sual</label><div class="field"><label>Bölmə</label><select data-builder-field="sectionId" data-qid="${q.id}">${s.sections.map(x=>`<option value="${x.id}" ${q.sectionId===x.id?'selected':''}>${esc(x.title)}</option>`).join('')}</select></div>${withOpts?`<div class="prop-divider"></div><div class="field"><label>Cavab variantları (hər sətirdə bir variant)</label><textarea data-builder-field="options" data-qid="${q.id}" style="min-height:125px">${esc(q.options.map(x=>x.label).join('\n'))}</textarea><small>İstədiyiniz qədər variant daxil edin.</small></div>${['image_choice','image_ab'].includes(q.type)?`<div class="field"><label>Şəkil URL-ləri (variantlarla eyni ardıcıllıqda)</label><textarea data-builder-field="images" data-qid="${q.id}">${esc(q.options.map(x=>x.image||'').join('\n'))}</textarea></div>`:''}`:''}${withRows?`<div class="prop-divider"></div><div class="field"><label>${q.type==='multitext'?'Mətn sahələrinin adları':'Matris sətirləri'} (hər sətirdə bir)</label><textarea data-builder-field="rows" data-qid="${q.id}">${esc(q.rows.join('\n'))}</textarea></div>${q.type!=='multitext'?`<div class="field"><label>Matris sütunları (hər sətirdə bir)</label><textarea data-builder-field="columns" data-qid="${q.id}">${esc(q.columns.join('\n'))}</textarea></div>`:''}`:''}${numeric?`<div class="prop-divider"></div><div class="form-grid"><div class="field"><label>Minimum</label><input type="number" data-builder-field="min" data-qid="${q.id}" value="${esc(q.settings.min??0)}"></div><div class="field"><label>Maksimum</label><input type="number" data-builder-field="max" data-qid="${q.id}" value="${esc(q.settings.max??10)}"></div></div>`:''}${q.type==='multiple'?`<div class="field"><label>Maksimum seçim sayı (0 = limitsiz)</label><input type="number" min="0" max="100" data-builder-field="maxSelect" data-qid="${q.id}" value="${esc(q.settings.maxSelect??0)}"></div>`:''}${q.type==='slider'?`<div class="field"><label>Addım dəyəri</label><input type="number" min="0.01" step="0.01" data-builder-field="step" data-qid="${q.id}" value="${esc(q.settings.step??1)}"></div>`:''}<div class="prop-divider"></div><div class="field"><label>Şərtli göstərilmə</label><select data-builder-field="conditionQuestion" data-qid="${q.id}"><option value="">Həmişə göstər</option>${s.questions.filter(x=>x.id!==q.id).map(x=>`<option value="${x.id}" ${q.condition?.questionId===x.id?'selected':''}>${esc(x.title.slice(0,60))}</option>`).join('')}</select><small>Bu sual yalnız əvvəlki sualın cavabından asılı olaraq göstərilə bilər.</small></div>${q.condition?`<div class="field"><label>Müqayisə</label><select data-builder-field="conditionOperator" data-qid="${q.id}">${[['equals','Bərabərdir'],['not_equals','Bərabər deyil'],['contains','Ehtiva edir'],['not_empty','Boş deyil'],['empty','Boşdur']].map(([v,n])=>`<option value="${v}" ${q.condition.operator===v?'selected':''}>${n}</option>`).join('')}</select></div><div class="field"><label>Cavab dəyəri</label><input data-builder-field="conditionValue" data-qid="${q.id}" value="${esc(q.condition.value)}" placeholder="Məsələn: Bəli"></div>`:''}</div><div class="hint">${ico('info',14)} Suallar seçilərək nizamlanır. Məzmun dəyişikliyi yadda saxlanana qədər yalnız redaktorda qalır.</div>`;}
function builderPreview(){const s=state.builder;return `<div class="preview-banner">${ico('eye',16)} Önizləmə — doldurulan cavablar yadda saxlanmır.</div><div class="card" style="overflow:hidden"><div class="interview-hero"><div class="tiny">ÖNİZLƏMƏ / ${s.estimatedMinutes} dəqiqə</div><h2>${esc(s.title)}</h2><p>${esc(s.description)}</p></div><div class="interview-section">${s.sections.map((sec,i)=>`<h3 style="margin:25px 0 10px">${i+1}. ${esc(sec.title)}</h3>${s.questions.filter(q=>q.sectionId===sec.id).map(q=>renderAnswer(q,{},true)).join('')}`).join('')}</div></div>`;}
// ——— DYNAMIC SURVEY RENDERER ———
const qVal=(answers,id)=>answers[id];
function variantFor(q,assignmentId){const options=q.options||[];return options.length?options[(q.id.charCodeAt(0)+(assignmentId?.charCodeAt(0)||0))%options.length]:null;}
function renderAnswer(q,answers={},preview=false){const val=qVal(answers,q.id),type=q.type, opts=q.options||[],min=Number(q.settings?.min??0),max=Math.min(100,Math.max(min+1,Number(q.settings?.max??10)));const checked=v=>Array.isArray(val)?val.includes(v):String(val??'')===String(v);const disabled=preview?'disabled':'';
let html='';const questionId=esc(q.id);
function options(checkbox=false,image=false){const raw=type==='yesno'?[{label:'Bəli'},{label:'Xeyr'}]:opts;return `<div class="choice-grid">${raw.map(o=>`<label class="choice-card ${checked(o.label)?'selected':''}" ${image?'style="align-items:start;flex-direction:column"':''}>${image&&o.image?`<img src="${esc(o.image)}" loading="lazy" alt="${esc(o.label)}" style="width:100%;height:100px;object-fit:cover;border-radius:7px">`:''}<span class="gap10"><input type="${checkbox?'checkbox':'radio'}" name="ans_${questionId}" data-answer="${questionId}" ${checked(o.label)?'checked':''} value="${esc(o.label)}" ${disabled}>${esc(o.label)}</span></label>`).join('')}</div>`;}
if(['single','multiple','yesno','image_choice'].includes(type))html=options(type==='multiple',type==='image_choice');
else if(type==='dropdown')html=`<select class="answer-input" data-answer="${questionId}" ${disabled}><option value="">Variant seçin...</option>${opts.map(o=>`<option value="${esc(o.label)}" ${checked(o.label)?'selected':''}>${esc(o.label)}</option>`).join('')}</select>`;
else if(['text_ab','image_ab'].includes(type)){const variant=variantFor(q,state.interview?.assignment?.id);html=`<div class="highlight-box" style="margin:0 0 10px">${type==='image_ab'&&variant?.image?`<img src="${esc(variant.image)}" alt="Vizual variant" style="max-width:100%;max-height:180px">`:esc(variant?.label||'Variant yoxdur')}</div><div class="choice-grid"><label class="choice-card ${(val?.answer==='Bəli'||checked('Bəli'))?'selected':''}"><input type="radio" name="ans_${questionId}" data-answer="${questionId}" value="Bəli" ${(val?.answer==='Bəli'||checked('Bəli'))?'checked':''} ${disabled}> Bəli</label><label class="choice-card ${(val?.answer==='Xeyr'||checked('Xeyr'))?'selected':''}"><input type="radio" name="ans_${questionId}" data-answer="${questionId}" value="Xeyr" ${(val?.answer==='Xeyr'||checked('Xeyr'))?'checked':''} ${disabled}> Xeyr</label></div>`;}
else if(['rating','nps','likert'].includes(type))html=`<div class="rating-group">${Array.from({length:Math.min(21,max-min+1)},(_,i)=>min+i).map(n=>`<button type="button" class="rating-btn ${Number(val)===n?'active':''}" data-action="numeric-answer" data-qid="${questionId}" data-value="${n}" ${disabled}>${n}</button>`).join('')}</div>${type==='nps'?'<div class="range-row mt12" style="max-width:445px"><span>Heç tövsiyə etmərəm</span><span>Mütləq tövsiyə edərəm</span></div>':''}`;
else if(type==='stars')html=`<div class="star-rating">${Array.from({length:Math.min(10,max)},(_,i)=>i+1).map(n=>`<button type="button" class="${Number(val)>=n?'active':''}" data-action="numeric-answer" data-qid="${questionId}" data-value="${n}" ${disabled}>★</button>`).join('')}</div>`;
else if(type==='slider')html=`<input class="answer-range" data-answer="${questionId}" type="range" min="${min}" max="${max}" step="${Number(q.settings?.step)||1}" value="${val??min}" ${disabled}><div class="range-row"><span>${min}</span><b class="slider-value" data-for="${questionId}" style="color:#6656e9">${val??min}</b><span>${max}</span></div>`;
else if(type==='consent')html=`<label class="choice-card" style="max-width:470px"><input type="checkbox" data-answer="${questionId}" value="Bəli" ${checked('Bəli')?'checked':''} ${disabled}> Razılıq verirəm</label>`;
else if(type.startsWith('matrix')){const rows=q.rows||[],cols=q.columns||[],multi=type==='matrix_multi',drop=type==='matrix_dropdown';html=`<div class="matrix-wrap"><table class="matrix"><thead><tr><th></th>${cols.map(c=>`<th>${esc(c)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr><td>${esc(row)}</td>${drop?`<td colspan="${cols.length}"><select class="answer-input" style="height:34px" data-answer="${questionId}" data-row="${esc(row)}" ${disabled}><option value="">Seçin...</option>${cols.map(col=>`<option value="${esc(col)}" ${(val||{})[row]===col?'selected':''}>${esc(col)}</option>`).join('')}</select></td>`:cols.map(col=>`<td><input type="${multi?'checkbox':'radio'}" name="mx_${questionId}_${esc(row)}" data-answer="${questionId}" data-row="${esc(row)}" value="${esc(col)}" ${multi?(Array.isArray((val||{})[row])&&(val||{})[row].includes(col)?'checked':''):((val||{})[row]===col?'checked':'')} ${disabled}></td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
else if(type==='multitext')html=(q.rows||[]).map(row=>`<div class="multitext-row"><label>${esc(row)}</label><input class="answer-input" data-answer="${questionId}" data-row="${esc(row)}" value="${esc((val||{})[row]||'')}" placeholder="Cavabı daxil edin" ${disabled}></div>`).join('');
else if(type==='ranking')html=`<p class="note">Hər variant üçün sıralama nömrəsi seçin (1 ən yüksəkdir).</p>${opts.map((o,i)=>`<div class="multitext-row"><label style="flex:1">${esc(o.label)}</label><select class="answer-input" style="max-width:110px" data-answer="${questionId}" data-row="${esc(o.label)}" ${disabled}><option value="">Sıra</option>${opts.map((_,j)=>`<option value="${j+1}" ${String((val||{})[o.label]||'')===String(j+1)?'selected':''}>${j+1}</option>`).join('')}</select></div>`).join('')}`;
else if(type==='bestworst')html=`<div class="form-grid"><div class="field"><label>Ən yaxşı</label><select class="answer-input" data-answer="${questionId}" data-row="best" ${disabled}><option value="">Seçin...</option>${opts.map(o=>`<option value="${esc(o.label)}" ${(val||{}).best===o.label?'selected':''}>${esc(o.label)}</option>`).join('')}</select></div><div class="field"><label>Ən pis</label><select class="answer-input" data-answer="${questionId}" data-row="worst" ${disabled}><option value="">Seçin...</option>${opts.map(o=>`<option value="${esc(o.label)}" ${(val||{}).worst===o.label?'selected':''}>${esc(o.label)}</option>`).join('')}</select></div></div>`;
else if(type==='file')html=`<input type="file" data-file-answer="${questionId}" accept=".jpg,.jpeg,.png,.webp,.pdf,.docx" ${disabled}><p class="note">Maksimum 2 MB, JPG / PNG / WebP / PDF / DOCX.${val?` <b>Fayl əlavə edilib.</b>`:''}</p>`;
else if(type==='paragraph'||type==='address')html=`<textarea class="answer-input answer-textarea" data-answer="${questionId}" placeholder="Cavabı buraya yazın..." ${disabled}>${esc(val??'')}</textarea>`;
else {const inputType=({email:'email',phone:'tel',number:'number',currency:'number',percentage:'number',date:'date',time:'time',datetime:'datetime-local'})[type]||'text';html=`<input class="answer-input" type="${inputType}" ${['number','currency','percentage'].includes(type)?`step="${type==='number'?1:'.01'}" ${type==='percentage'?'min="0" max="100"':''}`:''} data-answer="${questionId}" value="${esc(val??'')}" placeholder="Cavabı daxil edin..." ${disabled}>`}
return `<div class="answer-question" data-question="${questionId}"><div class="answer-qtitle">${esc(q.title)} ${q.required?'<span class="required">*</span>':''}</div>${q.description?`<div class="answer-desc">${esc(q.description)}</div>`:''}${html}</div>`;}
function conditionMatch(q,answers){if(!q.condition)return true;let value=answers[q.condition.questionId];let str=Array.isArray(value)?value.join(', '):value&&typeof value==='object'?Object.values(value).join(', '):String(value??'');switch(q.condition.operator){case'equals':return Array.isArray(value)?value.includes(q.condition.value):str===q.condition.value;case'not_equals':return str!==q.condition.value;case'contains':return str.includes(q.condition.value);case'not_empty':return str.trim()!=='';case'empty':return str.trim()==='';default:return true;}}
function activeQuestions(){const s=state.interview.survey;return s.questions.filter(q=>q.sectionId===s.sections[state.interviewIndex].id&&conditionMatch(q,state.interview.answers));}
function interviewPage(){const x=state.interview;if(!x)return empty('surveys','Müsahibə seçilməyib','Zəng tapşırıqları səhifəsindən respondent seçin.');if(state.interviewDone)return `<div class="card" style="max-width:680px;margin:60px auto">${successPage()}</div>`;const {survey:s,contact:c,assignment:a}=x,sec=s.sections[state.interviewIndex],locked=x.response?.status==='completed',p=(state.interviewIndex+1)/s.sections.length*100;return `${heading('CANLI MÜSAHİBƏ','Sorğunun doldurulması','Telefon danışığı zamanı cavabları bölmələr üzrə qeyd edin.',`<button class="btn" data-action="nav" data-page="tasks">${ico('back',15)} Tapşırıqlar</button>`)}<div class="interview-layout"><div class="card interview-main"><div class="interview-hero"><div class="tiny">SORĞU № ${state.interviewIndex+1} / ${s.sections.length} BÖLMƏ</div><h2>${esc(s.title)}</h2><p>${esc(s.description)}</p><div class="steps">${s.sections.map((_,i)=>`<button data-action="interview-step" data-index="${i}" class="${i===state.interviewIndex?'active':i<state.interviewIndex?'done':''}" title="${i+1}-ci bölmə"></button>`).join('')}</div></div><div class="interview-section"><div class="gap10" style="justify-content:space-between"><div><h3>${esc(sec.title)}</h3><p class="muted">${esc(sec.description||'Sualları ardıcıllıqla cavablandırın.')}</p></div><span class="pill">${Math.round(p)}%</span></div>${activeQuestions().map(q=>renderAnswer(q,x.answers,locked)).join('')||`<p class="note" style="padding:20px">Bu bölmədə göstəriləcək sual yoxdur.</p>`}<div id="interview-warning"></div></div><div class="interview-foot"><div class="gap10"><button class="btn" data-action="interview-prev" ${state.interviewIndex===0?'disabled':''}>${ico('back',14)} Geri</button><button class="btn" data-action="interview-save" ${locked?'disabled':''}>${ico('save',14)} Qaralama</button></div>${locked?`<button class="btn btn-primary" data-action="nav" data-page="tasks">${ico('check',14)} Baxış tamamlandı</button>`:`<button class="btn btn-primary" data-action="interview-next">${state.interviewIndex===s.sections.length-1?'Tamamla və göndər':'Növbəti bölmə'} ${ico(state.interviewIndex===s.sections.length-1?'check':'arrow',15)}</button>`}</div></div><div class="interview-aside"><div class="card person-card"><div class="person-head"><div class="person-avatar">${esc(initials(c.fullName))}</div><div><strong>${esc(c.fullName)}</strong><small>RESPONDENT PROFİLİ</small></div></div>${[['Telefon',c.phone],['Region',c.region||'—'],['Status',OUTCOME[a.status]],['Zəng cəhdi',String(a.attempts)],['Prioritet',a.priority==='high'?'Yüksək':'Normal']].map(([k,v])=>`<div class="info-pair"><span>${k}</span><span>${esc(v)}</span></div>`).join('')}<a class="call-cta" href="tel:${esc(c.phone.replace(/[^\d+]/g,''))}">${ico('phone',16)} Telefona zəng et</a><button class="btn w100" data-action="call-result" data-id="${a.id}">${ico('clock',14)} Zəng nəticəsini qeyd et</button></div><div class="card person-card mt20"><div class="aside-title">Sorğu bölmələri</div><div class="step-list">${s.sections.map((sc,i)=>`<button class="step-item ${i===state.interviewIndex?'active':i<state.interviewIndex?'done':''}" data-action="interview-step" data-index="${i}"><span>${i<state.interviewIndex?'✓':i+1}</span>${esc(sc.title)}</button>`).join('')}</div>${x.calls?.length?`<div class="separator"></div><div class="aside-title">Son zənglər</div>${x.calls.slice(0,3).map(call=>`<div class="call-history"><div class="history-date">${fmtTime(call.createdAt)}</div><div class="history-line">${outcomeBadge(call.outcome)} &nbsp; ${esc(call.notes||'')}</div></div>`).join('')}`:''}<div class="question-note">${ico('info',14)} Müsahibə zamanı dəyişiklikləri “Qaralama” düyməsi ilə mütəmadi saxlayın. <br><br>Ölçülən müddət: <b id="timer-display">${formatDuration(Math.round((Date.now()-x.startTime)/1000))}</b></div></div></div></div>`;}
function formatDuration(sec){return String(Math.floor(sec/60)).padStart(2,'0')+':'+String(sec%60).padStart(2,'0');}
function successPage(){const x=state.interview;return `<div class="success-state"><div class="confirm-illustration">${ico('check',34)}</div><h2>Müsahibə tamamlandı!</h2><p><b>${esc(x.contact.fullName)}</b> üzrə cavablar uğurla qeydə alındı.<br>Məlumatlar analitika bölməsində əlçatandır.</p><div class="gap10" style="justify-content:center;margin:28px auto 5px"><button class="btn btn-primary" data-action="nav" data-page="tasks">${ico('list',15)} Tapşırıqlara qayıt</button><button class="btn" data-action="nav" data-page="dashboard">${ico('dashboard',15)} İdarə paneli</button></div></div>`;}
function checkSection(){for(const q of activeQuestions()){const val=state.interview.answers[q.id];if(q.required&&(val==null||val===''||(Array.isArray(val)&&!val.length)||(typeof val==='object'&&val&&!Object.values(val).some(a=>Array.isArray(a)?a.length:a!==''&&a!=null))))return q.title+' — bu suala cavab verilməlidir.';if(q.type==='email'&&val&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(val))return q.title+' — e-poçt formatı yanlışdır.';}return '';}
function updateAnswer(node){if(!state.interview||state.page!=='interview')return;const id=node.dataset.answer;if(!id)return;const q=state.interview.survey.questions.find(q=>q.id===id);if(!q)return;let v;if(node.dataset.row){v={...(state.interview.answers[id]||{})};const row=node.dataset.row;if(q.type==='matrix_multi'){const checked=$$(`[data-answer="${id}"][data-row="${CSS.escape(row)}"]:checked`).map(x=>x.value);v[row]=checked;}else v[row]=node.value;}else if(node.type==='checkbox'){if(q.type==='consent')v=node.checked?'Bəli':'';else v=$$(`input[data-answer="${id}"]:checked`).map(x=>x.value);}else if(node.type==='range'||['number','currency','percentage'].includes(q.type))v=node.value===''?'':Number(node.value);else if(q.type==='text_ab'||q.type==='image_ab')v={variant:variantFor(q,state.interview.assignment.id)?.label||'',answer:node.value};else v=node.value;state.interview.answers[id]=v;state.dirty=true;if(node.type==='range'){$(`.slider-value[data-for="${id}"]`)?.replaceChildren(document.createTextNode(v));}if(['radio','checkbox','select-one'].includes(node.type)&&!node.dataset.row)render();}
async function loadInterview(id){const data=await request('/api/responses/assignment/'+id);state.interview={...data,answers:{...(data.response?.answers||{})},startTime:Date.now(),savedDuration:data.response?.durationSec||0};state.interviewIndex=0;state.interviewDone=false;state.page='interview';state.dirty=false;location.hash='#/interview';render();window.scrollTo(0,0);}
async function saveInterview(completed=false){const x=state.interview;if(!x)return;if(completed){let allErr='';for(let i=0;i<x.survey.sections.length;i++){state.interviewIndex=i;allErr=checkSection();if(allErr)break;}if(allErr){render();notify(allErr,true);return false;}}const duration=x.savedDuration+Math.round((Date.now()-x.startTime)/1000);const data=await api('/api/responses/assignment/'+x.assignment.id,{answers:x.answers,status:completed?'completed':'draft',durationSec:duration},'PUT');x.response=data.response;x.assignment=data.assignment;x.savedDuration=duration;x.startTime=Date.now();state.dirty=false;await refresh();if(completed){state.interviewDone=true;render();notify('Sorğu uğurla tamamlandı.');}else notify('Qaralama yadda saxlandı.');return true;}
// ——— MODALS ———
function openModal(title,subtitle,body,formName=''){const div=document.createElement('div');div.className='overlay';div.id='modal-overlay';div.innerHTML=`<div class="modal ${formName==='import'?'modal-wide':''}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-head"><div><h2>${esc(title)}</h2><p>${esc(subtitle)}</p></div><button class="modal-x" data-action="close-modal">${ico('close',18)}</button></div><form data-modal-form="${esc(formName)}"><div class="modal-body">${body}</div><div class="modal-foot"><button type="button" class="btn" data-action="close-modal">Ləğv et</button><button type="submit" class="btn btn-primary">${ico('check',15)} Təsdiqlə</button></div></form></div>`;document.body.append(div);div.addEventListener('click',e=>{if(e.target===div)div.remove();});div.querySelector('input:not([type=hidden]),textarea,select')?.focus();}
function closeModal(){$('#modal-overlay')?.remove();}
function formVal(form){const obj={};new FormData(form).forEach((v,k)=>obj[k]=v);return obj;}
function contactModal(id){const c=state.contacts.find(c=>c.id===id)||{};openModal(id?'Respondenti redaktə et':'Yeni respondent','Əlaqə məlumatlarını daxil edin.',`<input type="hidden" name="id" value="${esc(c.id||'')}"><div class="form-grid"><div class="field full"><label>Ad və soyad *</label><input name="fullName" required maxlength="150" value="${esc(c.fullName||'')}" placeholder="Məsələn: Leyla Məmmədova"></div><div class="field"><label>Telefon *</label><input name="phone" type="tel" required value="${esc(c.phone||'')}" placeholder="+994 50 123 45 67"></div><div class="field"><label>Region</label><input name="region" value="${esc(c.region||'')}" placeholder="Bakı"></div><div class="field full"><label>E-poçt</label><input name="email" type="email" value="${esc(c.email||'')}" placeholder="example@mail.az"></div><div class="field full"><label>Qeyd</label><textarea name="notes">${esc(c.notes||'')}</textarea></div></div>`,'contact');}
function userModal(id){const u=state.users.find(u=>u.id===id)||{};openModal(id?'Əməkdaşı redaktə et':'Yeni əməkdaş','Rol və giriş məlumatlarını idarə edin.',`<input name="id" type="hidden" value="${esc(u.id||'')}"><div class="form-grid"><div class="field full"><label>Ad və soyad *</label><input name="name" required value="${esc(u.name||'')}" placeholder="Ad Soyad"></div><div class="field"><label>İstifadəçi adı *</label><input name="username" ${id?'disabled':''} ${id?'':'required'} value="${esc(u.username||'')}" placeholder="operator3"></div><div class="field"><label>Rol</label><select name="role"><option value="agent" ${u.role==='agent'?'selected':''}>Operator</option><option value="admin" ${u.role==='admin'?'selected':''}>Administrator</option></select></div><div class="field full"><label>${id?'Yeni şifrə (dəyişmək istəmirsinizsə boş buraxın)':'Şifrə (ən azı 10 simvol) *'}</label><input name="password" type="password" autocomplete="new-password" ${id?'':'required'} minlength="${id?0:10}" placeholder="Güclü şifrə"></div>${id?`<div class="field full"><label>Hesab statusu</label><select name="active"><option value="true" ${u.active?'selected':''}>Aktiv</option><option value="false" ${!u.active?'selected':''}>Deaktiv</option></select></div>`:''}</div>`,'user');}
function assignModal(){const avail=state.surveys.filter(s=>s.status==='active');const users=state.users.filter(u=>u.active);const ids=[...state.selectedContacts];openModal('Yeni zəng təyinatı','Respondentləri aktiv sorğu və operatorla əlaqələndirin.',`<div class="form-grid"><div class="field full"><label>Sorğu *</label><select name="surveyId" required><option value="">Seçin...</option>${avail.map(s=>`<option value="${s.id}">${esc(s.title)}</option>`).join('')}</select></div>${state.user.role==='admin'?`<div class="field full"><label>Məsul operator *</label><select name="assignedTo" required><option value="">Seçin...</option>${users.map(u=>`<option value="${u.id}" ${u.id===state.user.id?'selected':''}>${esc(u.name)} (${u.role==='admin'?'Admin':'Operator'})</option>`).join('')}</select></div>`:''}<div class="field"><label>Prioritet</label><select name="priority"><option value="normal">Normal</option><option value="high">Yüksək</option><option value="low">Aşağı</option></select></div><div class="field"><label>Respondentlər</label><div class="pill" style="margin-top:11px">${ids.length?ids.length+' seçilmiş respondent':'Aşağıdan seçin'}</div></div><div class="field full"><label>${ids.length?'Əlavə respondentlər':'Respondent seçimi *'}</label><select name="contactIds" multiple size="8" style="height:auto;padding:8px"><option value="" disabled>Ctrl / Cmd ilə bir neçə seçin</option>${state.contacts.map(c=>`<option value="${c.id}" ${ids.includes(c.id)?'selected':''}>${esc(c.fullName)} · ${esc(c.phone)}</option>`).join('')}</select><small>Respondent bazası səhifəsində toplu seçim də edə bilərsiniz.</small></div></div>`,'assign');}
function resultModal(id){const a=state.assignments.find(a=>a.id===id);if(!a)return;openModal('Zəng nəticəsini qeyd et',`${a.contact?.fullName||''} · ${a.contact?.phone||''}`,`<input type="hidden" name="id" value="${esc(a.id)}"><div class="field"><label>Danışığın nəticəsi *</label><select name="outcome" required>${['pending','in_progress','callback','no_answer','busy','refused'].map(v=>`<option value="${v}" ${a.status===v?'selected':''}>${OUTCOME[v]}</option>`).join('')}</select><small>“Tamamlandı” nəticəsi sorğu forması göndərildikdə avtomatik qeydə alınır.</small></div><div class="field"><label>Təkrar zəng vaxtı (lazımdırsa)</label><input type="datetime-local" name="callbackAt" value="${datetimeLocal(a.callbackAt)}"></div><div class="field"><label>Operator qeydi</label><textarea name="notes" placeholder="Zəng haqqında qeyd...">${esc(a.notes||'')}</textarea></div>`,'result');}
function surveySettings(){const s=state.builder;openModal('Sorğu parametrləri','Əsas məlumatlar və yayımlanma vəziyyəti.',`<div class="form-grid"><div class="field full"><label>Sorğu adı *</label><input required name="title" value="${esc(s.title)}"></div><div class="field full"><label>Təsvir</label><textarea name="description">${esc(s.description||'')}</textarea></div><div class="field"><label>Kateqoriya</label><input name="category" value="${esc(s.category||'Ümumi')}"></div><div class="field"><label>Təxmini müddət (dəqiqə)</label><input name="estimatedMinutes" min="1" max="180" type="number" value="${s.estimatedMinutes||5}"></div><div class="field"><label>Status</label><select name="status">${['draft','active','paused','archived'].map(v=>`<option value="${v}" ${s.status===v?'selected':''}>${OUTCOME[v]}</option>`).join('')}</select></div><div class="field"><label>Vurğu rəngi</label><input name="accent" type="color" value="${esc(s.accent||'#6756ea')}" style="padding:6px"></div></div>`,'survey-settings');}
function sectionModal(id){const sec=state.builder.sections.find(s=>s.id===id)||{};openModal(id?'Bölməni dəyiş':'Yeni bölmə','Sorğunu mövzular üzrə qruplaşdırın.',`<input name="id" type="hidden" value="${esc(sec.id||'')}"><div class="field"><label>Bölmə adı *</label><input name="title" required value="${esc(sec.title||'')}"></div><div class="field"><label>İzah</label><textarea name="description">${esc(sec.description||'')}</textarea></div>`,'section');}
function importModal(){if(state.user.role!=='admin')return notify('CSV idxalı üçün admin icazəsi tələb olunur.',true);openModal('Respondentlərin CSV idxalı','CSV faylında başlıqlar: fullName, phone, region, email, notes',`<div class="hint" style="margin-bottom:17px">İlk sətirdə sütun adları olmalıdır. <b>fullName</b> (və ya ad), <b>phone</b> (və ya telefon) mütləqdir. Ayırıcı kimi <b>,</b> və ya <b>;</b> dəstəklənir.</div><div class="field"><label>CSV faylını seçin</label><input type="file" accept=".csv,text/csv" id="import-file" required style="padding:11px"></div><div class="field"><label>Önizləmə</label><div id="import-preview" class="hint">Fayl seçilməyib.</div></div>`,'import');}
function passwordModal(){openModal('Şifrəni dəyiş','Hesabınızı qorumaq üçün güclü şifrə istifadə edin.',`<div class="field"><label>Cari şifrə *</label><input name="oldPassword" type="password" required></div><div class="field"><label>Yeni şifrə *</label><input name="newPassword" type="password" required minlength="10" placeholder="Ən azı 10 simvol"></div><div class="field"><label>Yeni şifrə (təkrar) *</label><input name="confirm" type="password" required minlength="10"></div>`,'password');}
function statusModal(id){const s=state.surveys.find(s=>s.id===id);if(!s)return;openModal('Sorğu statusu','Aktiv sorğular operatorlara görünür.',`<input type="hidden" name="id" value="${esc(id)}"><div class="field"><label>Yeni status</label><select name="status">${['draft','active','paused','archived'].map(x=>`<option value="${x}" ${s.status===x?'selected':''}>${OUTCOME[x]}</option>`).join('')}</select></div>`,'status');}
function responseDetails(id){const r=state.report?.responses?.find(x=>x.id===id);if(!r)return;const survey=state.surveys.find(s=>s.id===state.report.survey.id);openModal('Müsahibə cavabları',`${r.contact} · ${fmtTime(r.submittedAt)}`,`<div style="max-height:55vh;overflow:auto">${survey.questions.map((q,i)=>`<div class="info-pair" style="display:block"><b style="display:block;margin-bottom:9px">${i+1}. ${esc(q.title)}</b><span>${esc(typeof r.answers[q.id]==='object'?JSON.stringify(r.answers[q.id]):r.answers[q.id]??'—')}</span></div>`).join('')}</div>`,'read-only');$('.modal-foot')?.remove();}
function csvParse(text,delimiter=','){const lines=[];let row=[],value='',quotes=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'&&quotes&&text[i+1]==='"'){value+='"';i++;}else if(c==='"')quotes=!quotes;else if(!quotes&&(c===delimiter||c==='\n'||c==='\r')){if(c===delimiter){row.push(value);value='';}else if(c==='\n'){row.push(value);value='';if(row.some(x=>x.trim()))lines.push(row);row=[];}}else value+=c;}row.push(value);if(row.some(x=>x.trim()))lines.push(row);return lines;}
function csvContacts(text){const firstLine=text.split(/\r?\n/)[0];const delim=(firstLine.match(/;/g)||[]).length>(firstLine.match(/,/g)||[]).length?';':',';const rows=csvParse(text.replace(/^\ufeff/,''),delim);const head=(rows.shift()||[]).map(x=>x.trim().toLowerCase());const col=(line,...names)=>{const i=head.findIndex(h=>names.some(n=>h===n));return i>=0?line[i]?.trim()||'':'';};return rows.map(line=>({fullName:col(line,'fullname','name','ad','ad soyad','ad və soyad','soyad'),phone:col(line,'phone','tel','telefon','mobil'),email:col(line,'email','e-poçt','e-mail'),region:col(line,'region','rayon','şəhər'),notes:col(line,'notes','qeyd')})).filter(x=>x.fullName&&x.phone);}
// ——— USER INTERACTIONS ———
function findBuilderQ(id){return state.builder?.questions.find(q=>q.id===id);}
function updateBuilderField(el){const q=findBuilderQ(el.dataset.qid),key=el.dataset.builderField;if(!q)return;const v=el.type==='checkbox'?el.checked:el.value;switch(key){case'required':q.required=!!v;break;case'options':{const old=q.options||[],images=old.map(o=>o.image);q.options=String(v).split(/\r?\n/).filter(x=>x.trim()).slice(0,80).map((label,i)=>({id:old[i]?.id||mkId(),label:label.trim(),image:images[i]||''}));break;}case'images':{const images=String(v).split(/\r?\n/);q.options.forEach((o,i)=>o.image=images[i]||'');break;}case'rows':case'columns':q[key]=String(v).split(/\r?\n/).map(x=>x.trim()).filter(Boolean);break;case'min':case'max':case'maxSelect':case'step':q.settings[key]=Number(v);break;case'conditionQuestion':q.condition=v?{questionId:v,operator:q.condition?.operator||'equals',value:q.condition?.value||''}:null;break;case'conditionOperator':if(q.condition)q.condition.operator=v;break;case'conditionValue':if(q.condition)q.condition.value=v;break;default:q[key]=v;}state.dirty=true;}
async function dispatchAction(el){const action=el.dataset.action,id=el.dataset.id;try{
 switch(action){
 case'nav':state.mobile=false;navigate(el.dataset.page);break;
 case'toggle-mobile':state.mobile=!state.mobile;render();break;
 case'close-mobile':state.mobile=false;render();break;
 case'logout':await api('/api/logout',{});state.user=null;state.report=null;state.builder=null;location.hash='';renderLogin();notify('Hesabdan çıxış edildi.');break;
 case'refresh':await refresh();render();notify('Məlumatlar yeniləndi.');break;
 case'new-survey':{const s={title:'Yeni sorğu',description:'',category:'Ümumi',status:'draft',estimatedMinutes:5,sections:[{id:mkId(),title:'Bölmə 1',description:''}],questions:[]};const r=await api('/api/surveys',s);await refresh();makeBuilder(r.survey);notify('Yeni sorğu yaradıldı.');break;}
 case'edit-survey':{const s=state.surveys.find(x=>x.id===id);if(s)makeBuilder(s);break;}
 case'duplicate-survey':{if(!confirm('Bu sorğunun surətini yaratmaq istəyirsiniz?'))break;const r=await api('/api/surveys/'+id+'/duplicate',{});await refresh();makeBuilder(r.survey);notify('Sorğunun surəti yaradıldı.');break;}
 case'survey-status':statusModal(id);break;
 case'new-contact':contactModal();break;
 case'edit-contact':contactModal(id);break;
 case'import-contacts':importModal();break;
 case'assign-selected':assignModal();break;
 case'start-interview':await loadInterview(id);break;
 case'call-result':resultModal(id||state.interview?.assignment.id);break;
 case'new-user':userModal();break;
 case'edit-user':userModal(id);break;
 case'change-password':passwordModal();break;
 case'open-report':state.report=await request('/api/reports/'+id);state.reportSurveyId=id;state.reportTab='summary';render();break;
 case'close-report':state.report=null;render();break;
 case'report-tab':state.reportTab=el.dataset.tab;render();break;
 case'response-details':responseDetails(id);break;
 case'export-report':window.location.href='/api/export/'+id;notify('CSV ixracı başlanıldı.');break;
 case'close-modal':closeModal();break;
 case'select-all-contacts':{const selected=el.checked;filtered(state.contacts,c=>c.fullName+' '+c.phone+' '+c.email+' '+c.region).forEach(c=>selected?state.selectedContacts.add(c.id):state.selectedContacts.delete(c.id));render();break;}
 case'save-builder':{const r=await api('/api/surveys/'+state.builder.id,state.builder,'PUT');state.builder=r.survey;state.dirty=false;await refresh();render();notify('Sorğu yadda saxlanıldı.');break;}
 case'add-question':{const s=state.builder;const q=newQuestion(el.dataset.type,el.dataset.section||state.builderSection||s.sections[0].id);s.questions.push(q);state.builderQ=q.id;state.builderSection=q.sectionId;state.preview=false;state.propOpen=true;state.dirty=true;render();break;}
 case'select-question':state.builderQ=id;state.builderSection=findBuilderQ(id)?.sectionId;state.preview=false;state.propOpen=true;render();break;
 case'clone-question':{const i=state.builder.questions.findIndex(q=>q.id===id);const clone=structuredClone(state.builder.questions[i]);clone.id=mkId();clone.title+=' (surət)';state.builder.questions.splice(i+1,0,clone);state.builderQ=clone.id;state.propOpen=true;state.dirty=true;render();break;}
 case'delete-question':if(confirm('Bu sualı silmək istəyirsiniz?')){state.builder.questions=state.builder.questions.filter(q=>q.id!==id);state.builderQ=state.builder.questions[0]?.id||null;state.dirty=true;render();}break;
 case'move-question':{const s=state.builder,idx=s.questions.findIndex(q=>q.id===id),section=s.questions[idx].sectionId,matching=s.questions.map((q,i)=>q.sectionId===section?i:-1).filter(i=>i>=0),pos=matching.indexOf(idx),target=matching[pos+Number(el.dataset.direction)];if(target!==undefined){[s.questions[idx],s.questions[target]]=[s.questions[target],s.questions[idx]];state.dirty=true;render();}break;}
 case'add-section':sectionModal();break;
 case'edit-section':sectionModal(id);break;
 case'delete-section':{const s=state.builder;if(!confirm('Bölmə silinəcək. Bu bölmədəki suallar ilk bölməyə köçürüləcək.'))break;s.sections=s.sections.filter(x=>x.id!==id);s.questions.filter(q=>q.sectionId===id).forEach(q=>q.sectionId=s.sections[0].id);state.builderSection=s.sections[0].id;state.dirty=true;render();break;}
 case'open-properties':state.propOpen=true;render();break;
 case'close-properties':state.propOpen=false;render();break;
 case'survey-settings':surveySettings();break;
 case'builder-preview':state.preview=!state.preview;render();break;
 case'numeric-answer':if(state.interview&&state.page==='interview'){state.interview.answers[el.dataset.qid]=Number(el.dataset.value);state.dirty=true;render();}break;
 case'interview-prev':if(state.interviewIndex>0){state.interviewIndex--;render();}break;
 case'interview-step':state.interviewIndex=Number(el.dataset.index);render();break;
 case'interview-save':await saveInterview(false);break;
 case'interview-next':{const err=checkSection();if(err){notify(err,true);const warning=$('#interview-warning');if(warning)warning.innerHTML=`<div class="page-error">${ico('info',14)} ${esc(err)}</div>`;break;}if(state.interviewIndex===state.interview.survey.sections.length-1){if(confirm('Sorğunu yekunlaşdırmaq istəyirsiniz? Tamamlanan cavab redaktə edilə bilməz.'))await saveInterview(true);}else {await saveInterview(false);state.interviewIndex++;render();window.scrollTo(0,0);}break;}
 default:break;
 }
 }catch(e){notify(e.message,true);}}
async function handleForm(form){const kind=form.dataset.modalForm,values=formVal(form);if(!kind)return;try{
 if(kind==='contact'){const url=values.id?'/api/contacts/'+values.id:'/api/contacts';await api(url,values,values.id?'PUT':'POST');notify('Respondent məlumatları saxlanıldı.');}
 else if(kind==='user'){const data={...values,active:values.active!=='false'};if(!values.password)delete data.password;await api(values.id?'/api/users/'+values.id:'/api/users',data,values.id?'PUT':'POST');notify('Əməkdaş hesabı saxlanıldı.');}
 else if(kind==='assign'){const select=form.querySelector('[name="contactIds"]');const ids=[...new Set([...state.selectedContacts,...[...select.selectedOptions].map(x=>x.value).filter(Boolean)])];if(!ids.length)throw Error('Ən azı bir respondent seçilməlidir.');const r=await api('/api/assignments',{surveyId:values.surveyId,assignedTo:values.assignedTo,priority:values.priority,contactIds:ids});state.selectedContacts.clear();notify(`${r.count} yeni tapşırıq yaradıldı.`);}
 else if(kind==='result'){const d={outcome:values.outcome,callbackAt:values.callbackAt?new Date(values.callbackAt).toISOString():null,notes:values.notes,durationSec:state.interview?Math.round((Date.now()-state.interview.startTime)/1000):0};const r=await api('/api/assignments/'+values.id+'/calls',d);if(state.interview?.assignment.id===values.id)state.interview.assignment=r.assignment;notify('Zəng nəticəsi qeyd edildi.');}
 else if(kind==='survey-settings'){Object.assign(state.builder,{title:values.title,description:values.description,category:values.category,status:values.status,estimatedMinutes:Number(values.estimatedMinutes),accent:values.accent});state.dirty=true;notify('Parametrlər redaktora tətbiq edildi. Yadda saxlayın.');}
 else if(kind==='section'){const s=state.builder;let sec=s.sections.find(x=>x.id===values.id);if(sec){sec.title=values.title;sec.description=values.description;}else{sec={id:mkId(),title:values.title,description:values.description};s.sections.push(sec);}state.builderSection=sec.id;state.dirty=true;notify('Bölmə yeniləndi.');}
 else if(kind==='status'){const s=state.surveys.find(s=>s.id===values.id);await api('/api/surveys/'+s.id,{...s,status:values.status},'PUT');notify('Sorğu statusu dəyişdirildi.');}
 else if(kind==='password'){if(values.newPassword!==values.confirm)throw Error('Yeni şifrələr uyğun gəlmir.');await api('/api/me/password',{oldPassword:values.oldPassword,newPassword:values.newPassword},'PUT');closeModal();state.user=null;renderLogin();notify('Şifrə dəyişdirildi. Yenidən daxil olun.');return;}
 else if(kind==='import'){const file=$('#import-file')?.files?.[0];if(!file)throw Error('CSV faylı seçin.');const text=await file.text();const records=csvContacts(text);if(!records.length)throw Error('CSV-də fullName və phone sütunları üzrə məlumat tapılmadı.');const r=await api('/api/contacts/bulk',{contacts:records});notify(`${r.count} respondent idxal edildi.`);}
 else return;
 closeModal();if(['survey-settings','section'].includes(kind))render();else{await refresh();render();}
 }catch(e){notify(e.message,true);}}
let searchDebounce=0;
document.addEventListener('click',e=>{const action=e.target.closest('[data-action]');if(!action)return;e.preventDefault();e.stopPropagation();dispatchAction(action);});
document.addEventListener('submit',async e=>{const form=e.target;if(form.id==='login-form'){e.preventDefault();const data=formVal(form),button=$('button[type=submit]',form);button.disabled=true;button.textContent='Yoxlanılır...';try{const out=await api('/api/login',data);state.user=out.user;await refresh();state.page='dashboard';location.hash='#/dashboard';render();notify('Sistemə uğurla daxil oldunuz.');}catch(error){const box=$('#login-error');if(box)box.innerHTML=`<div class="page-error">${esc(error.message)}</div>`;}finally{if(button){button.disabled=false;button.innerHTML=`Sistemə daxil ol ${ico('arrow',17)}`;}}}else if(form.dataset.modalForm){e.preventDefault();await handleForm(form);}});
document.addEventListener('input',e=>{const el=e.target;if(el.dataset.builderField!==undefined){updateBuilderField(el);return;}if(el.id==='global-search'||el.dataset.localSearch!==undefined){state.filter=el.value;clearTimeout(searchDebounce);searchDebounce=setTimeout(()=>{const focus=el.id==='global-search'?'#global-search':'[data-local-search]';const pos=el.selectionStart;render();const input=$(focus);if(input){input.focus();try{input.setSelectionRange(pos,pos);}catch{}}},220);return;}if(el.dataset.answer!==undefined){updateAnswer(el);return;}});
document.addEventListener('change',async e=>{const el=e.target;if(el.dataset.builderField!==undefined){if(el.tagName==='SELECT'||el.type==='checkbox')render();return;}if(el.dataset.statusFilter!==undefined){state.statusFilter=el.value;render();return;}if(el.dataset.answer!==undefined){updateAnswer(el);return;}if(el.dataset.fileAnswer!==undefined){try{const file=el.files?.[0];if(!file)return;if(file.size>2*1024*1024)throw new Error('Fayl 2 MB-dan böyükdür.');const allowed=['image/jpeg','image/png','image/webp','application/pdf','application/vnd.openxmlformats-officedocument.wordprocessingml.document'];if(!allowed.includes(file.type))throw new Error('Yalnız JPG, PNG, WebP, PDF və DOCX yükləmək olar.');const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=()=>reject(new Error('Fayl oxuna bilmədi.'));reader.readAsDataURL(file);});const result=await api('/api/uploads',{name:file.name,mime:file.type,data});state.interview.answers[el.dataset.fileAnswer]=result.id;state.dirty=true;notify('Fayl uğurla əlavə edildi.');render();}catch(err){notify(err.message,true);}return;}if(el.classList.contains('contact-check')){el.checked?state.selectedContacts.add(el.dataset.id):state.selectedContacts.delete(el.dataset.id);render();return;}if(el.id==='import-file'){const file=el.files?.[0];if(file){const text=await file.text();const records=csvContacts(text);const x=$('#import-preview');if(x)x.textContent=`${records.length} uyğun respondent müəyyən edildi. Fayl: ${file.name}`;}}});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();});
setInterval(()=>{if(state.page==='interview'&&state.interview){const sec=state.interview.savedDuration+Math.round((Date.now()-state.interview.startTime)/1000);if($('#timer-display'))$('#timer-display').textContent=formatDuration(sec);}},1000);
window.addEventListener('beforeunload',e=>{if(state.dirty&&['builder','interview'].includes(state.page)){e.preventDefault();e.returnValue='';}});
init();
